// ==UserScript==
// @name         优学院助手 · 陈千语·墨韵主题美化
// @namespace    https://github.com/BrocadeHutHost
// @version      5.6.0
// @description  为「优学院助手 + 文档工具（标准版）」提供“陈千语·墨韵”主题美化：墨色为主、蓝红点睛，沉稳内敛。仅作用于标准版面板内部，不改动宿主网页。采用“增强”模式——仅覆盖主题 CSS 变量并追加装饰，不替换标准版 DOM。使用前需先安装并启用标准版脚本。
// @author       BrocadeHutHost
// @match        *://*/*
// @run-at       document-idle
// @grant        GM_addStyle
// @grant        GM_getValue
// @grant        GM_setValue
// @grant        GM_registerMenuCommand
// @homepageURL  https://github.com/BrocadeHutHost/DGUT-ULearningTakeQuizzesAssistant
// @license      AGPL-3.0-only
// ==/UserScript==


(function () {
    'use strict';

    const TAG = '[陈千语墨韵]';

    const CHQ_BG_BASE64 = "data:image/png;base64,";

    const CHQ_SIDEBAR_BG_BASE64 = "data:image/jpeg;base64,";

    const CONFIG = {
        background: GM_getValue('chq_panel_bg', true),
        particles: GM_getValue('chq_particles', true),
        particleCount: 8,
        waitTimeoutMs: 20000
    };

    function svgUrl(svg) {
        return 'url("data:image/svg+xml;charset=utf-8,' + encodeURIComponent(svg) + '")';
    }

    const SEAL_SVG = "<svg xmlns='http://www.w3.org/2000/svg' viewBox='0 0 100 100'><circle cx='50' cy='50' r='36' fill='none' stroke='#5B8FBD' stroke-width='7'/><circle cx='50' cy='50' r='21' fill='none' stroke='#3E6F9E' stroke-width='4'/><circle cx='50' cy='50' r='9' fill='#B85A5A'/></svg>";

    const FAB_SVG = `
        <svg class="chq-fab-icon" viewBox="0 0 100 100" width="46" height="46" fill="none" aria-hidden="true">
            <circle class="chq-ring" cx="50" cy="50" r="34" stroke-width="6"/>
            <circle class="chq-ring-in" cx="50" cy="50" r="20" stroke-width="3"/>
            <circle class="chq-dot" cx="50" cy="50" r="9"/>
        </svg>`;

    const THEME_VARS_LIGHT = `
        --dgut-primary: #3E6F9E !important;
        --dgut-primary-hover: #315C86 !important;
        --dgut-on-primary: #FFFFFF !important;
        --dgut-primary-container: rgba(62,111,158,.14) !important;
        --dgut-on-primary-container: #1E3A55 !important;
        --dgut-secondary-container: #E4E6E9 !important;
        --dgut-on-secondary-container: #3A4048 !important;
        --dgut-surface: #EDEEF0 !important;
        --dgut-surface-2: #E4E6E9 !important;
        --dgut-surface-3: #F7F8FA !important;
        --dgut-on-surface: #1A1D22 !important;
        --dgut-on-surface-variant: #4A5058 !important;
        --dgut-outline: #C4C8CE !important;
        --dgut-outline-variant: #D5D9DE !important;
        --dgut-error: #9E3F3F !important;
        --dgut-error-container: rgba(158,63,63,.14) !important;
        --dgut-on-error-container: #6E2A2A !important;
        --dgut-success: #3E6F9E !important;
        --dgut-success-container: rgba(62,111,158,.14) !important;
        --dgut-on-success-container: #1E3A55 !important;
        --dgut-warn: #9E3F3F !important;
        --dgut-warn-container: rgba(158,63,63,.14) !important;
        --dgut-on-warn-container: #6E2A2A !important;
        --dgut-info-container: rgba(62,111,158,.10) !important;
        --dgut-on-info-container: #1E3A55 !important;
        --dgut-input-bg: #E4E6E9 !important;
        --dgut-hover-overlay: rgba(0,0,0,.05) !important;
        --dgut-color-scheme: light !important;
    `;

    const THEME_VARS_DARK = `
        --dgut-primary: #5B8FBD !important;
        --dgut-primary-hover: #7BA9CF !important;
        --dgut-on-primary: #0B0D10 !important;
        --dgut-primary-container: rgba(62,111,158,.20) !important;
        --dgut-on-primary-container: #C9D8E6 !important;
        --dgut-secondary-container: #232A33 !important;
        --dgut-on-secondary-container: #A0A6AD !important;
        --dgut-surface: #0B0D10 !important;
        --dgut-surface-2: #12151A !important;
        --dgut-surface-3: #1A1F26 !important;
        --dgut-on-surface: #E8EAED !important;
        --dgut-on-surface-variant: #A0A6AD !important;
        --dgut-outline: #2E3640 !important;
        --dgut-outline-variant: #232A33 !important;
        --dgut-error: #B85A5A !important;
        --dgut-error-container: rgba(158,63,63,.20) !important;
        --dgut-on-error-container: #E8B4B4 !important;
        --dgut-success: #5B8FBD !important;
        --dgut-success-container: rgba(62,111,158,.20) !important;
        --dgut-on-success-container: #C9D8E6 !important;
        --dgut-warn: #B85A5A !important;
        --dgut-warn-container: rgba(158,63,63,.20) !important;
        --dgut-on-warn-container: #E8B4B4 !important;
        --dgut-info-container: rgba(62,111,158,.14) !important;
        --dgut-on-info-container: #C9D8E6 !important;
        --dgut-input-bg: #12151A !important;
        --dgut-hover-overlay: rgba(255,255,255,.06) !important;
        --dgut-color-scheme: dark !important;
    `;

    const CHQ_VARS_LIGHT = `
        --chq-ink: #EDEEF0;
        --chq-ink-2: #E4E6E9;
        --chq-ink-3: #F7F8FA;
        --chq-ink-4: #FFFFFF;
        --chq-line: #C4C8CE;
        --chq-blue: #3E6F9E;
        --chq-blue-lite: #5B8FBD;
        --chq-red: #9E3F3F;
        --chq-red-lite: #B85A5A;
    `;

    const CHQ_VARS_DARK = `
        --chq-ink: #0B0D10;
        --chq-ink-2: #12151A;
        --chq-ink-3: #1A1F26;
        --chq-ink-4: #232A33;
        --chq-line: #2E3640;
        --chq-blue: #3E6F9E;
        --chq-blue-lite: #5B8FBD;
        --chq-red: #9E3F3F;
        --chq-red-lite: #B85A5A;
    `;

    const STYLE_ID = 'chq-skin-style';

    function buildCSS() {
        return `
        :root { ${THEME_VARS_LIGHT} }
        html.dgut-theme-dark { ${THEME_VARS_DARK} }

        :root { ${CHQ_VARS_LIGHT} --chq-seal: ${svgUrl(SEAL_SVG)}; }
        html.dgut-theme-dark { ${CHQ_VARS_DARK} }

        :root {
            --chq-bg-mask: linear-gradient(rgba(237,238,240,.30), rgba(237,238,240,.30));
            --chq-sidebar-mask: linear-gradient(rgba(228,230,233,.32), rgba(228,230,233,.32));
        }
        html.dgut-theme-dark {
            --chq-bg-mask: linear-gradient(rgba(11,13,16,.30), rgba(11,13,16,.30));
            --chq-sidebar-mask: linear-gradient(rgba(18,21,26,.36), rgba(18,21,26,.36));
        }

        #dgut-main-panel.chq-panel-bg {
            background-color: var(--dgut-surface) !important;
            background-image: var(--chq-bg-mask, none), var(--chq-bg-image, none) !important;
            background-size: cover, cover !important;
            background-position: center, center !important;
            background-repeat: no-repeat, no-repeat !important;
        }
        #dgut-main-panel.chq-panel-bg > div:not(#dgut-panel-header),
        #dgut-main-panel.chq-panel-bg > div:nth-child(2) > div:nth-child(2),
        #dgut-main-panel.chq-panel-bg [style*="var(--dgut-surface);"] {
            background-color: transparent !important;
            background-image: none !important;
        }
        #dgut-main-panel.chq-panel-bg > div > div {
            background-color: transparent !important;
        }
        #dgut-main-panel.chq-panel-bg #dgut-sidebar {
            background-image: var(--chq-sidebar-mask, none), var(--chq-sidebar-bg, linear-gradient(180deg, var(--chq-ink-2), var(--chq-ink))) !important;
            background-size: cover, cover !important;
            background-position: center, center !important;
            background-repeat: no-repeat, no-repeat !important;
        }
        #dgut-main-panel.chq-panel-bg #dgut-panel-body {
            background: transparent !important;
        }
        #dgut-main-panel.chq-panel-bg #dgut-status-bar {
            background: color-mix(in srgb, var(--chq-ink-2) 62%, transparent) !important;
        }
        #dgut-main-panel.chq-panel-bg .dgut-card {
            background: color-mix(in srgb, var(--chq-ink-3) 60%, transparent) !important;
            -webkit-backdrop-filter: blur(3px) saturate(1.05);
            backdrop-filter: blur(3px) saturate(1.05);
        }
        #dgut-main-panel:not(.chq-panel-bg) #dgut-panel-body { background: var(--dgut-surface); }

        #dgut-main-panel {
            border-radius: 18px !important;
            border: none !important;
            box-shadow:
                0 0 0 1px var(--chq-line),
                0 0 0 2px rgba(62,111,158,.45),
                0 0 18px rgba(62,111,158,.22),
                0 18px 52px rgba(0,0,0,.55) !important;
            overflow: hidden !important;
        }

        #dgut-panel-header {
            background: linear-gradient(120deg, var(--chq-ink-2) 0%, var(--chq-ink-3) 60%, var(--chq-ink-2) 100%) !important;
            position: relative;
            padding-top: 13px !important;
            padding-bottom: 13px !important;
            box-shadow: inset 0 -1px 0 rgba(62,111,158,.55) !important;
        }
        #dgut-panel-header > svg { display: none !important; }
        #dgut-panel-header::before {
            content: '';
            width: 22px; height: 22px; flex: none;
            background-image: var(--chq-seal);
            background-size: contain; background-repeat: no-repeat; background-position: center;
            filter: drop-shadow(0 1px 2px rgba(0,0,0,.5));
        }
        #dgut-panel-header::after {
            content: '';
            position: absolute; inset: 0;
            background: radial-gradient(160px 46px at 92% -30%, rgba(184,90,90,.30), transparent 72%);
            pointer-events: none;
        }
        #dgut-panel-header .panel-title { letter-spacing: .4px; color: var(--dgut-on-surface) !important; }

        #dgut-panel-close { transition: transform .15s, background .15s, color .15s !important; }
        #dgut-panel-close:hover { transform: rotate(90deg); background: rgba(158,63,63,.35) !important; }

        #dgut-sidebar {
            background: linear-gradient(180deg, var(--chq-ink-2), var(--chq-ink)) !important;
            border: none !important;
            border-radius: 12px !important;
            margin: 10px 6px 10px 10px !important;
            overflow: hidden auto !important;
            box-shadow:
                0 0 0 1px var(--chq-line),
                0 0 0 1.5px rgba(62,111,158,.40),
                0 2px 10px rgba(0,0,0,.35) !important;
        }
        .dgut-nav-label { color: var(--chq-blue-lite) !important; opacity: .80; letter-spacing: 1px; }
        .dgut-nav { border-radius: 10px !important; }
        .dgut-nav:hover {
            background: linear-gradient(90deg, rgba(62,111,158,.22), transparent) !important;
            color: var(--dgut-on-surface) !important;
        }
        .dgut-nav.dgut-tab-active {
            background: linear-gradient(90deg, rgba(62,111,158,.32), transparent) !important;
            color: var(--chq-blue-lite) !important;
            box-shadow: inset 3px 0 0 var(--chq-blue-lite);
        }

        #dgut-panel-body { padding: 12px 14px !important; }
        #dgut-panel-footer-version { color: var(--dgut-on-surface-variant) !important; opacity: .8; }
        #dgut-status-bar { border-top: 1px solid rgba(62,111,158,.35) !important; }

        .dgut-card {
            border-radius: 14px !important;
            border: none !important;
            box-shadow:
                0 0 0 0.5px var(--chq-line),
                0 0 0 1px rgba(62,111,158,.30),
                0 4px 18px rgba(0,0,0,.35) !important;
        }
        .dgut-section-title { position: relative; padding-left: 12px; }
        .dgut-section-title::before {
            content: '';
            position: absolute; left: 0; top: 50%; transform: translateY(-50%);
            width: 4px; height: 14px; border-radius: 2px;
            background: linear-gradient(180deg, var(--chq-blue-lite), var(--chq-red-lite));
        }

        .dgut-hint { border-radius: 12px !important; border: 1px solid rgba(62,111,158,.28) !important; }

        .dgut-input, .dgut-textarea, .dgut-select { border-radius: 10px !important; border-color: var(--chq-line) !important; }
        .dgut-input:focus, .dgut-textarea:focus, .dgut-select:focus {
            border-color: var(--chq-blue-lite) !important;
            box-shadow: 0 0 0 3px rgba(62,111,158,.22) !important;
        }

        .dgut-btn { border-radius: 10px !important; transition: transform .14s, box-shadow .14s, background .14s !important; }
        .dgut-btn:not(:disabled):hover { transform: translateY(-1px); }
        .dgut-btn-primary {
            background: linear-gradient(120deg, var(--chq-blue), var(--chq-blue-lite)) !important;
            color: #0B0D10 !important;
            box-shadow: 0 2px 10px rgba(62,111,158,.42) !important;
        }
        .dgut-btn-primary:not(:disabled):hover { box-shadow: 0 4px 16px rgba(91,143,189,.55) !important; }

        .dgut-sign-course { border-radius: 10px !important; }
        .dgut-sign-course.active { box-shadow: 0 0 0 2px rgba(62,111,158,.35) inset; }

        .dgut-log { border-radius: 10px !important; }

        .dgut-tab-btn.active { border-bottom-width: 2px !important; color: var(--chq-blue-lite) !important; }

        #dgut-doc-preview-box { border-radius: 10px !important; }
        #dgut-sig-canvas { border-radius: 10px !important; }

        #dgut-main-panel ::-webkit-scrollbar-thumb {
            background: linear-gradient(180deg, var(--chq-blue), var(--chq-blue-lite)) !important;
            border: 2px solid var(--chq-ink) !important;
        }

        #dgut-toast-card {
            border-radius: 14px !important;
            border: none !important;
            border-left: 5px solid var(--chq-blue-lite) !important;
            box-shadow:
                0 0 0 1px var(--chq-line),
                0 0 0 1.5px rgba(62,111,158,.45),
                0 18px 52px rgba(0,0,0,.55) !important;
            background-image: radial-gradient(200px 60px at 100% 0, rgba(158,63,63,.10), transparent 70%) !important;
        }
        .dgut-toast-progress { background: linear-gradient(90deg, var(--chq-blue-lite), var(--chq-red-lite)) !important; }

        #dgut-mini-panel {
            border-radius: 50% !important;
            border: none !important;
            background: radial-gradient(circle at 34% 28%, var(--chq-ink-3), var(--chq-ink)) !important;
            box-shadow:
                0 0 0 1px var(--chq-line),
                0 0 0 2px rgba(62,111,158,.50),
                0 6px 22px rgba(0,0,0,.55) !important;
            transition: box-shadow .2s, transform .2s, background .2s !important;
        }
        #dgut-mini-panel:hover {
            transform: scale(1.08) !important;
            box-shadow:
                0 0 0 1px var(--chq-line),
                0 0 0 2px var(--chq-blue-lite),
                0 0 22px rgba(91,143,189,.60),
                0 10px 30px rgba(0,0,0,.60) !important;
        }
        #dgut-mini-panel .chq-ring { stroke: var(--chq-blue-lite); transition: stroke .2s; }
        #dgut-mini-panel .chq-ring-in { stroke: var(--chq-blue); transition: stroke .2s; }
        #dgut-mini-panel .chq-dot { fill: var(--chq-red-lite); transition: fill .2s; }
        #dgut-mini-panel:hover .chq-ring-in { animation: chqSpin 4s linear infinite; transform-origin: 50px 50px; }
        #dgut-mini-panel:hover .chq-dot { fill: var(--chq-red); }

        #chq-particles {
            position: absolute; inset: 0; overflow: hidden;
            pointer-events: none; z-index: 6;
            border-radius: inherit;
        }
        .chq-ink {
            position: absolute; top: -30px; width: 10px; height: 10px;
            border-radius: 50%;
            opacity: 0;
            animation-name: chqInkFall;
            animation-timing-function: ease-in-out;
            animation-iteration-count: infinite;
            will-change: transform, opacity;
        }

        @keyframes chqInkFall {
            0%   { transform: translateY(-30px) translateX(0) scale(.7); opacity: 0; }
            18%  { opacity: .55; }
            50%  { transform: translateY(300px) translateX(10px) scale(1); opacity: .5; }
            82%  { opacity: .4; }
            100% { transform: translateY(600px) translateX(-6px) scale(.8); opacity: 0; }
        }
        @keyframes chqSpin {
            from { transform: rotate(0deg); }
            to   { transform: rotate(360deg); }
        }
        @media (prefers-reduced-motion: reduce) {
            .chq-ink { animation: none !important; opacity: 0 !important; }
            #dgut-mini-panel:hover .chq-ring-in { animation: none !important; }
        }
        `;
    }

    function injectStyles() {
        if (document.getElementById(STYLE_ID)) return;
        const el = document.createElement('style');
        el.id = STYLE_ID;
        el.textContent = buildCSS();
        (document.head || document.documentElement).appendChild(el);
    }

    function applyBackground() {
        const root = document.documentElement;
        const panelRaw = (CHQ_BG_BASE64 || '').replace(/\s+/g, '');
        const sideRaw = (CHQ_SIDEBAR_BG_BASE64 || '').replace(/\s+/g, '');
        root.style.setProperty('--chq-bg-image', panelRaw
            ? 'url("' + panelRaw + '")'
            : 'linear-gradient(135deg, var(--chq-ink) 0%, var(--chq-ink-2) 60%, rgba(62,111,158,.22) 100%)');
        root.style.setProperty('--chq-sidebar-bg', sideRaw
            ? 'url("' + sideRaw + '")'
            : 'linear-gradient(180deg, var(--chq-ink-2), var(--chq-ink))');
    }

    function mountParticles(panel) {
        if (!CONFIG.particles || !panel) return;
        if (panel.querySelector('#chq-particles')) return;
        const layer = document.createElement('div');
        layer.id = 'chq-particles';
        for (let i = 0; i < CONFIG.particleCount; i++) {
            const ink = document.createElement('div');
            ink.className = 'chq-ink';
            const red = Math.random() < 0.25;
            const size = (6 + Math.random() * 8).toFixed(1);
            ink.style.left = (Math.random() * 100).toFixed(2) + '%';
            ink.style.width = size + 'px';
            ink.style.height = size + 'px';
            ink.style.background = red ? 'rgba(184,90,90,.85)' : 'rgba(91,143,189,.85)';
            ink.style.boxShadow = red
                ? '0 0 6px rgba(184,90,90,.55)'
                : '0 0 6px rgba(91,143,189,.55)';
            ink.style.animationDelay = (Math.random() * 10).toFixed(2) + 's';
            ink.style.animationDuration = (7 + Math.random() * 6).toFixed(2) + 's';
            layer.appendChild(ink);
        }
        panel.appendChild(layer);
    }

    function enhancePanel() {
        const panel = document.getElementById('dgut-main-panel');
        if (!panel) return;
        applyBackground();
        if (CONFIG.background) {
            panel.classList.add('chq-panel-bg');
            paintPanelBackground(panel);
        }
        paintSidebarBackground(panel.querySelector('#dgut-sidebar'));
        mountParticles(panel);
    }

    function paintSidebarBackground(sidebar) {
        if (!sidebar) return;
        const raw = (CHQ_SIDEBAR_BG_BASE64 || '').replace(/\s+/g, '');
        const dark = document.documentElement.classList.contains('dgut-theme-dark');
        const mask = dark
            ? 'linear-gradient(rgba(18,21,26,.36), rgba(18,21,26,.36))'
            : 'linear-gradient(rgba(228,230,233,.32), rgba(228,230,233,.32))';
        const img = raw
            ? 'url("' + raw + '")'
            : (dark
                ? 'linear-gradient(180deg, #12151A, #0B0D10)'
                : 'linear-gradient(180deg, #E4E6E9, #EDEEF0)');
        sidebar.style.setProperty('background-color', 'transparent', 'important');
        sidebar.style.setProperty('background-image', mask + ', ' + img, 'important');
        sidebar.style.setProperty('background-size', 'cover, cover', 'important');
        sidebar.style.setProperty('background-position', 'center, center', 'important');
        sidebar.style.setProperty('background-repeat', 'no-repeat, no-repeat', 'important');
    }

    function paintPanelBackground(panel) {
        const raw = (CHQ_BG_BASE64 || '').replace(/\s+/g, '');
        const dark = document.documentElement.classList.contains('dgut-theme-dark');
        const mask = dark
            ? 'linear-gradient(rgba(11,13,16,.30), rgba(11,13,16,.30))'
            : 'linear-gradient(rgba(237,238,240,.30), rgba(237,238,240,.30))';
        const img = raw
            ? 'url("' + raw + '")'
            : (dark
                ? 'linear-gradient(135deg, #0B0D10 0%, #12151A 60%, rgba(62,111,158,.22) 100%)'
                : 'linear-gradient(135deg, #EDEEF0 0%, #E4E6E9 60%, rgba(62,111,158,.22) 100%)');
        panel.style.setProperty('background-color', 'transparent', 'important');
        panel.style.setProperty('background-image', mask + ', ' + img, 'important');
        panel.style.setProperty('background-size', 'cover, cover', 'important');
        panel.style.setProperty('background-position', 'center, center', 'important');
        panel.style.setProperty('background-repeat', 'no-repeat, no-repeat', 'important');
        const row = panel.children[1];
        if (row) {
            row.style.setProperty('background', 'transparent', 'important');
            row.style.setProperty('background-image', 'none', 'important');
            Array.prototype.forEach.call(row.children, function (child) {
                if (child.id === 'dgut-sidebar') return;
                child.style.setProperty('background', 'transparent', 'important');
                child.style.setProperty('background-image', 'none', 'important');
            });
        }
        const body = panel.querySelector('#dgut-panel-body');
        if (body) {
            body.style.setProperty('background', 'transparent', 'important');
            body.style.setProperty('background-image', 'none', 'important');
        }
        const status = panel.querySelector('#dgut-status-bar');
        if (status) status.style.setProperty('background', 'transparent', 'important');
    }

    function enhanceFab() {
        const mini = document.getElementById('dgut-mini-panel');
        if (!mini) return;
        if (mini.dataset.chqEnhanced === '1') return;
        mini.dataset.chqEnhanced = '1';
        mini.classList.add('chq-fab');
        mini.innerHTML = FAB_SVG;
        if (!mini.getAttribute('title')) mini.setAttribute('title', '打开优学院助手');
    }

    function standardPresent() {
        return !!(document.getElementById('dgut-main-panel') || document.getElementById('dgut-mini-panel'));
    }

    let activated = false;
    function activate(why) {
        if (activated) return;
        activated = true;
        log('已检测到标准版（' + why + '），开始应用陈千语·墨韵美化。');
        if (CONFIG.background) applyBackground();
        enhancePanel();
        enhanceFab();
        watchDom();
    }

    let observer = null;
    let themeObserver = null;
    function watchDom() {
        if (observer) return;
        observer = new MutationObserver(() => {
            if (document.getElementById('dgut-mini-panel')) enhanceFab();
            if (!activated && standardPresent()) { activate('DOM 变化'); return; }
            if (activated && document.getElementById('dgut-main-panel')) enhancePanel();
        });
        observer.observe(document.body || document.documentElement, { childList: true });
        if (!themeObserver) {
            themeObserver = new MutationObserver(() => {
                const panel = document.getElementById('dgut-main-panel');
                if (!panel) return;
                if (CONFIG.background) paintPanelBackground(panel);
                paintSidebarBackground(panel.querySelector('#dgut-sidebar'));
            });
            themeObserver.observe(document.documentElement, { attributes: true, attributeFilter: ['class'] });
        }
    }

    function waitForStandard() {
        if (standardPresent()) { activate('初始检测'); return; }
        watchDom();
        const start = Date.now();
        const timer = setInterval(() => {
            if (standardPresent()) { clearInterval(timer); activate('轮询'); return; }
            if (Date.now() - start > CONFIG.waitTimeoutMs) {
                clearInterval(timer);
                log('未检测到标准版脚本，未激活美化（仅保留无副作用样式）。');
            }
        }, 500);
    }

    function log() {
        try { console.log(TAG, ...arguments); } catch (e) {}
    }

    function registerMenus() {
        try {
            if (typeof GM_registerMenuCommand !== 'function') return;
            GM_registerMenuCommand('切换陈千语·墨韵面板背景（当前：' + (CONFIG.background ? '开' : '关') + '）', () => {
                GM_setValue('chq_panel_bg', !CONFIG.background);
                location.reload();
            });
            GM_registerMenuCommand('切换墨点粒子（当前：' + (CONFIG.particles ? '开' : '关') + '）', () => {
                GM_setValue('chq_particles', !CONFIG.particles);
                location.reload();
            });
        } catch (e) {}
    }

    function boot() {
        injectStyles();
        registerMenus();
        waitForStandard();
    }

    if (document.readyState === 'loading') {
        document.addEventListener('DOMContentLoaded', boot, { once: true });
    } else {
        boot();
    }
})();
